mapper.select:
SELECT 
FROM employee_investment_declarations d
JOIN employees e ON d.employee_id = e.id
LEFT JOIN departments dept ON e.department_id = dept.id
WHERE d.company_id = #{companyId}

    AND d.financial_year = #{financialYear}


    AND d.status = #{status}

ORDER BY d.updated_at DESC, e.employee_code ASC
